+  }
+  const sideDoors = [doorFL, doorFR, doorRL, doorRR];
+  for (let i = 0; i < sideDoors.length; i++) {
+    const d = sideDoors[i];
+    for (let k = 0; k < 2; k++) {
+      const sign = d.pos.z > 0 ? 1 : -1;
+      glassParts.push(addGlass(
+        'sg' + i + k,
+        d.pos.x + (k === 0 ? -0.06 : 0.07),
+        d.pos.y + d.hy * 0.15,
+        d.pos.z + sign * (doorT * 0.5 + 0.012),
+        doorLen * 0.38, doorH * 0.42, 0.012,
+        70
+      ));
+    }
+  }
+
+  function addHead(z) {
+    return makePart({
+      name: z > 0 ? 'hL' : 'hR',
+      x: bumperF.pos.x + bumperF.hx + 0.045,
+      y: bumperF.pos.y + bumperF.hy * 0.15,
+      z,
+      sx: 0.08, sy: 0.1, sz: 0.16,
+      mass: massOf('head', 2), mat: lampMat,
+      contactLimit: 1500, shockLimit: 36
+    });
+  }
+  const headL = addHead(narrowW * 0.28);
+  const headR = addHead(-narrowW * 0.28);
+
+  function fix(a, b, impulseLimit) {
+    const pa = a.pos, pb = b.pos;
+    const mid = { x: (pa.x + pb.x) / 2, y: (pa.y + pb.y) / 2, z: (pa.z + pb.z) / 2 };
+    const raw = world.createImpulseJoint(RAPIER.JointData.fixed(
+      { x: mid.x - pa.x, y: mid.y - pa.y, z: mid.z - pa.z }, IDQ,
+      { x: mid.x - pb.x, y: mid.y - pb.y, z: mid.z - pb.z }, IDQ
+    ), a.body, b.body, true);
+    joints.push({ raw, a, b, alive: true, impulseLimit, shockA: a.shockLimit, shockB: b.shockLimit });
+  }
+  function hingeWheel(host, wheel) {
+    const pa = host.pos, pb = wheel.pos;
+    const raw = world.createImpulseJoint(RAPIER.JointData.revolute(
+      { x: pb.x - pa.x, y: pb.y - pa.y, z: pb.z - pa.z }, { x: 0, y: 0, z: 1 },
+      { x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 }
+    ), host.body, wheel.body, true);
+    joints.push({ raw, a: host, b: wheel, alive: true, impulseLimit: 420, shockA: 1e9, shockB: wheel.shockLimit });
+  }
+
+  fix(bumperR, rearBody, 1e9);
+  fix(rearBody, cabin, 1e9);
+  fix(cabin, clipI, 1e9);
+  fix(clipI, clipO, 1e9);
+  fix(clipO, nose, 1e9);
+  fix(nose, bumperF, 1e9);
+  fix(hoodF, nose, 1e9);
+  fix(hoodF, hoodR, 1e9);
+  fix(hoodR, clipI, 1e9);
+  fix(trunkLid, rearBody, 1e9);
+  fix(doorFL, cabin, 1e9);
+  fix(doorFR, cabin, 1e9);
+  fix(doorRL, cabin, 1e9);
+  fix(doorRR, cabin, 1e9);
+  fix(headL, bumperF, 1e9);
+  fix(headR, bumperF, 1e9);
+  for (const g of glassParts) {
+    const host = g.name.startsWith('sg') ? sideDoors[Number(g.name[2])] || cabin : cabin;
+    fix(g, host, 1e9);
+  }
+  hingeWheel(clipO, wheelFL);
+  hingeWheel(clipO, wheelFR);
+  hingeWheel(rearBody, wheelRL);
+  hingeWheel(rearBody, wheelRR);
+
+  const fenderGeo = new THREE.BoxGeometry(wheelR * 1.3, 0.08, wheelW * 0.9);
+  function fender(host, axle, z) {
+    const m = new THREE.Mesh(fenderGeo, paintMat);
+    m.position.set((startCenter + axle) - host.pos.x, wheelR * 0.92 - host.pos.y, z - host.pos.z);
+    m.castShadow = true;
+    host.mesh.add(m);
+  }
+  fender(clipO, frontAxle, wheelZ);
+  fender(clipO, frontAxle, -wheelZ);
+  fender(rearBody, rearAxle, wheelZ);
+  fender(rearBody, rearAxle, -wheelZ);
+
+  const maxBlob = parts.length + brickBodies.length;
+  const blobOp = new Float32Array(maxBlob);
+  blobGeo.setAttribute('aOpacity', new THREE.InstancedBufferAttribute(blobOp, 1).setUsage(THREE.DynamicDrawUsage));
+  const blobs = new THREE.InstancedMesh(blobGeo, blobMat, maxBlob);
+  blobs.userData.keepGeo = true;
+  blobs.frustumCulled = false;
+  blobs.renderOrder = 2;
+  blobs.count = maxBlob;
+  group.add(blobs);
+  state.blobs = blobs;
+  state.blobOp = blobOp;
+  state.blobCount = maxBlob;
+
+  const sparkPos = new Float32Array(48 * 3);
+  const sparkGeo = new THREE.BufferGeometry();
+  sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPos, 3));
+  const sparkPts = new THREE.Points(sparkGeo, new THREE.PointsMaterial({
+    color: 0xffc27a, size: 0.07, transparent: true, opacity: 0.95, depthWrite: false, sizeAttenuation: true
+  }));
+  group.add(sparkPts);
+  const dustPos = new Float32Array(40 * 3);
+  const dustGeo = new THREE.BufferGeometry();
+  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
+  const dustPts = new THREE.Points(dustGeo, new THREE.PointsMaterial({
+    color: 0xb7aea2, size: 0.28, transparent: true, opacity: 0.35, depthWrite: false, sizeAttenuation: true
+  }));
+  group.add(dustPts);
+  state.sparkPts = sparkPts;
+  state.dustPts = dustPts;
+  state.sparkPos = sparkPos;
+  state.dustPos = dustPos;
+
+  const halfShadow = Math.max(26, s.trackLength * 0.62);
+  const sc = sun.shadow.camera;
+  sc.left = -halfShadow;
+  sc.right = halfShadow;
+  sc.top = halfShadow * 0.48;
+  sc.bottom = -halfShadow * 0.48;
+  sc.near = 0.5;
+  sc.far = 130;
+  sc.updateProjectionMatrix();
+  sun.position.set(s.trackLength * 0.28, 38, 20);
+  sun.target.position.set(s.trackLength * 0.62, 0.4, 0);
+  sun.target.updateMatrixWorld();
+
+  state.lookWall = wallFront + spanX * 0.35;
+  sim = state;
+  if (viewMode === 'orbit') snapOrbit();
+}
+
+function jointImpulse(raw) {
+  try {
+    if (raw && typeof raw.impulses === 'function') {
+      const v = raw.impulses();
+      if (typeof v === 'number') return Math.abs(v);
+      if (v && typeof v.length === 'number') {
+        let s = 0;
+        for (let i = 0; i < v.length; i++) s += v[i] * v[i];
+        return Math.sqrt(s);
+      }
+    }
+  } catch (e) { /* API optional */ }
+  return 0;
+}
+
+function killJoint(j) {
+  if (!j.alive) return;
+  j.alive = false;
+  sim.world.removeImpulseJoint(j.raw, true);
+}
+
+function spawnBurst(x, y, z) {
+  const rng = sim.rng;
+  for (let i = 0; i < 14; i++) {
+    const a = rng() * Math.PI * 2;
+    const sp = 1.5 + rng() * 5;
+    sim.sparks.push({
+      x, y: y + 0.2, z,
+      vx: Math.cos(a) * sp * 0.55,
+      vy: 1.2 + rng() * 4.5,
+      vz: Math.sin(a) * sp,
+      life: 0.18 + rng() * 0.28
+    });
+  }
+  for (let i = 0; i < 18; i++) {
+    sim.dust.push({
+      x: x + (rng() - 0.5) * 1.4,
+      y: 0.15 + rng() * 0.35,
+      z: z + (rng() - 0.5) * 1.6,
+      vx: (rng() - 0.5) * 2.2,
+      vy: 0.35 + rng() * 1.4,
+      vz: (rng() - 0.5) * 2.2,
+      life: 0.7 + rng() * 0.9
+    });
+  }
+}
+
+function laySkid() {
+  if (sim.skidLaid) return;
+  sim.skidLaid = true;
+  for (const w of sim.wheels) {
+    const p = w.body.translation();
+    const m = new THREE.Mesh(skidGeo, skidMat);
+    m.userData.keepGeo = true;
+    m.position.set(p.x - 1.15, 0.025, p.z);
+    m.receiveShadow = false;
+    sim.group.add(m);
+  }
+}
+
+function physicsStep() {
+  const s = sim.settings;
+  const cabin = sim.cabin.body;
+  if (sim.driving) {
+    const b = sim.bumperF;
+    const bx = b.body.translation().x + b.hx;
+    const nextV = Math.min(s.impactSpeed, sim.driveV + sim.accel * FIXED);
+    const reach = bx + nextV * FIXED;
+    if (reach >= sim.wallFront - 0.02) {
+      sim.driveV = nextV;
+      sim.driving = false;
+    } else {
+      sim.driveV = nextV;
+    }
+    for (const p of sim.parts) {
+      const vy = p.body.linvel().y;
+      p.body.setLinvel({ x: sim.driveV, y: vy, z: 0 }, true);
+      p.body.setAngvel({ x: 0, y: 0, z: p.isWheel ? -sim.driveV / sim.wheelR : 0 }, true);
+    }
+  }
+
+  sim.prevVx = cabin.linvel().x;
+  sim.world.step(sim.eventQueue);
+
+  const vx = cabin.linvel().x;
+  sim.shock = (sim.prevVx - vx) / FIXED;
+  sim.time += FIXED;
+  if (sim.shake > 0) sim.shake = Math.max(0, sim.shake - FIXED);
+
+  sim.eventQueue.drainContactForceEvents((ev) => {
+    const c1 = sim.world.getCollider(ev.collider1());
+    const c2 = sim.world.getCollider(ev.collider2());
+    if (!c1 || !c2) return;
+    const b1 = c1.parent();
+    const b2 = c2.parent();
+    const A = sim.meta.get(b1.handle);
+    const B = sim.meta.get(b2.handle);
+    if (!A || !B) return;
+    const f = typeof ev.totalForceMagnitude === 'function' ? ev.totalForceMagnitude() : 0;
+    const carBrick = (A.type === 'car' && B.type === 'brick') || (B.type === 'car' && A.type === 'brick');
+    if (carBrick) {
+      sim.armed = true;
+      sim.driving = false;
+      const car = A.type === 'car' ? A : B;
+      car.hit = Math.max(car.hit, f);
+      if (!sim.impacted) {
+        sim.impacted = true;
+        sim.shake = 0.42;
+        const p = sim.bumperF.body.translation();
+        spawnBurst(p.x, p.y, p.z);
+        laySkid();
+      }
+    } else if (sim.armed && A.type === 'car' && B.type === 'car') {
+      A.hit = Math.max(A.hit, f * 0.65);
+      B.hit = Math.max(B.hit, f * 0.65);
+    }
+  });
+
+  if (sim.armed) {
+    for (const j of sim.joints) {
+      if (!j.alive) continue;
+      const imp = jointImpulse(j.raw);
+      const hit = j.a.hit > j.a.contactLimit || j.b.hit > j.b.contactLimit;
+      const byImp = imp > j.impulseLimit;
+      const byShock = sim.shock > Math.min(j.shockA, j.shockB);
+      if (hit || byImp || byShock) killJoint(j);
+    }
+  }
+  for (const p of sim.parts) p.hit = 0;
+
+  if (sim.impacted) {
+    sim.impactSteps++;
+    tailMat.emissiveIntensity = 3.4;
+    if (sim.impactSteps < 8 && sim.impactSteps % 2 === 0) {
+      const p = sim.bumperF.body.translation();
+      const rng = sim.rng;
+      for (let i = 0; i < 4; i++) {
+        sim.dust.push({
+          x: p.x + (rng() - 0.5),
+          y: 0.2,
+          z: p.z + (rng() - 0.5) * 1.2,
+          vx: (rng() - 0.5) * 1.4,
+          vy: 0.4 + rng(),
+          vz: (rng() - 0.5) * 1.4,
+          life: 0.6 + rng() * 0.4
+        });
+      }
+    }
+  }
+
+  const g = s.gravity;
+  for (let i = sim.sparks.length - 1; i >= 0; i--) {
+    const p = sim.sparks[i];
+    p.life -= FIXED;
+    p.vy -= g * FIXED;
+    p.x += p.vx * FIXED;
+    p.y += p.vy * FIXED;
+    p.z += p.vz * FIXED;
+    if (p.life <= 0 || p.y < 0) sim.sparks.splice(i, 1);
+  }
+  for (let i = sim.dust.length - 1; i >= 0; i--) {
+    const p = sim.dust[i];
+    p.life -= FIXED;
+    p.vy -= g * 0.25 * FIXED;
+    p.x += p.vx * FIXED;
+    p.y += p.vy * FIXED;
+    p.z += p.vz * FIXED;
+    if (p.life <= 0 || p.y < 0) sim.dust.splice(i, 1);
+  }
+}
+
+function syncGraphics() {
+  for (const p of sim.parts) {
+    const t = p.body.translation();
+    const r = p.body.rotation();
+    p.mesh.position.set(t.x, t.y, t.z);
+    p.mesh.quaternion.set(r.x, r.y, r.z, r.w);
+  }
+  const dummy = scratch;
+  for (let i = 0; i < sim.brickBodies.length; i++) {
+    const b = sim.brickBodies[i];
+    const t = b.translation();
+    const r = b.rotation();
+    dummy.position.set(t.x, t.y, t.z);
+    dummy.quaternion.set(r.x, r.y, r.z, r.w);
+    dummy.scale.set(1, 1, 1);
+    dummy.updateMatrix();
+    sim.group.children.find(() => false);
+    const mesh = sim.brickMesh || null;
+  }
+  const brickMesh = sim.group.children.find((o) => o.isInstancedMesh && o !== sim.blobs);
+  sim.brickMesh = brickMesh;
+  if (brickMesh) {
+    for (let i = 0; i < sim.brickBodies.length; i++) {
+      const b = sim.brickBodies[i];
+      const t = b.translation();
+      const r = b.rotation();
+      dummy.position.set(t.x, t.y, t.z);
+      dummy.quaternion.set(r.x, r.y, r.z, r.w);
+      dummy.scale.set(1, 1, 1);
+      dummy.updateMatrix();
+      brickMesh.setMatrixAt(i, dummy.matrix);
+    }
+    brickMesh.instanceMatrix.needsUpdate = true;
+  }
+
+  const op = sim.blobOp;
+  const attr = sim.blobs.geometry.getAttribute('aOpacity');
+  let n = 0;
+  function blob(x, y, z, halfH, radius) {
+    const gap = y - halfH;
+    const fade = clamp(1 - gap / 0.9, 0, 1);
+    op[n] = 0.42 * fade;
+    const sc = radius * (0.85 + 0.15 * fade);
+    dummy.position.set(x, 0.03, z);
+    dummy.quaternion.identity();
+    dummy.scale.set(fade > 0.02 ? sc : 0.0001, 1, fade > 0.02 ? sc : 0.0001);
+    dummy.updateMatrix();
+    sim.blobs.setMatrixAt(n, dummy.matrix);
+    n++;
+  }
+  for (const p of sim.parts) {
+    const t = p.body.translation();
+    blob(t.x, t.y, t.z, p.halfH, p.blobR);
+  }
+  const bh = sim.settings.brickHeight * 0.5;
+  const br = Math.max(sim.settings.brickWidth, sim.settings.brickDepth) * 0.45;
+  for (const b of sim.brickBodies) {
+    const t = b.translation();
+    blob(t.x, t.y, t.z, bh, br);
+  }
+  for (; n < sim.blobCount; n++) op[n] = 0;
+  attr.needsUpdate = true;
+  sim.blobs.instanceMatrix.needsUpdate = true;
+
+  const sp = sim.sparkPos;
+  for (let i = 0; i < 48; i++) {
+    const p = sim.sparks[i];
+    const o = i * 3;
+    if (p) { sp[o] = p.x; sp[o + 1] = p.y; sp[o + 2] = p.z; }
+    else { sp[o] = 0; sp[o + 1] = -10; sp[o + 2] = 0; }
+  }
+  sim.sparkPts.geometry.attributes.position.needsUpdate = true;
+  const dp = sim.dustPos;
+  for (let i = 0; i < 40; i++) {
+    const p = sim.dust[i];
+    const o = i * 3;
+    if (p) { dp[o] = p.x; dp[o + 1] = p.y; dp[o + 2] = p.z; }
+    else { dp[o] = 0; dp[o + 1] = -10; dp[o + 2] = 0; }
+  }
+  sim.dustPts.geometry.attributes.position.needsUpdate = true;
+  sim.dustPts.material.opacity = 0.28;
+}
+
+function snapOrbit() {
+  const focusX = sim.lookWall - 1.2;
+  controls.target.set(focusX, 1.05, 0);
+  camera.up.set(0, 1, 0);
+  camera.fov = 45;
+  camera.position.set(focusX - 11, 4.6, 8.6);
+  camera.updateProjectionMatrix();
+  controls.update();
+}
+
+function updateCamera() {
+  if (!sim) return;
+  const t = sim.cabin.body.translation();
+  if (viewMode === 'orbit') {
+    controls.update();
+    return;
+  }
+  camera.up.set(0, 1, 0);
+  if (viewMode === 'impact') {
+    const span = Math.max(0.001, sim.wallFront - sim.startCenter);
+    const p = clamp((t.x - sim.startCenter) / span, 0, 1);
+    const u = p * p * (3 - 2 * p);
+    const lookX = lerp(sim.startCenter + 3, sim.lookWall - 0.4, 0.25 + 0.75 * u);
+    camTarget.set(lookX, 1.05, 0);
+    camera.fov = 42;
+    camera.position.set(
+      lerp(sim.wallFront - 18, sim.wallFront - 8.2, u),
+      lerp(5.6, 3.15, u),
+      lerp(10.5, 6.6, u)
+    );
+    camera.lookAt(camTarget);
+  } else if (viewMode === 'follow') {
+    camera.fov = 50;
+    camera.position.set(t.x - 7.5, t.y + 2.55, t.z + 3.7);
+    camera.lookAt(Math.min(sim.wallFront + 1.2, t.x + 4.8), t.y + 0.65, t.z * 0.4);
+  } else if (viewMode === 'top') {
+    camera.fov = 48;
+    camera.up.set(0, 0, -1);
+    const mid = sim.settings.trackLength * 0.5;
+    camera.position.set(mid, Math.max(42, sim.settings.trackLength * 1.05), 0.02);
+    camera.lookAt(mid, 0, 0);
+  }
+  if (sim.shake > 0 && (viewMode === 'impact' || viewMode === 'follow')) {
+    const k = sim.shake / 0.42;
+    const mag = k * k * 0.1;
+    camera.position.x += Math.sin(sim.time * 86) * mag;
+    camera.position.y += Math.sin(sim.time * 121) * mag * 0.45;
+    camera.position.z += Math.cos(sim.time * 97) * mag;
+  }
+  camera.updateProjectionMatrix();
+}
+
+function setPaused(v) {
+  paused = v;
+  document.getElementById('pauseBtn').textContent = paused ? 'Play' : 'Pause';
+}
+function highlight(attr, value) {
+  document.querySelectorAll('#bar button[' + attr + ']').forEach((b) => {
+    b.classList.toggle('on', b.getAttribute(attr) === String(value));
+  });
+}
+
+document.getElementById('pauseBtn').onclick = () => setPaused(!paused);
+document.getElementById('replay').onclick = () => {
+  setPaused(false);
+  tailMat.emissiveIntensity = 0.55;
+  build(readSettings());
+};
+document.getElementById('apply').onclick = () => {
+  setPaused(false);
+  tailMat.emissiveIntensity = 0.55;
+  const s = readSettings();
+  writeSettings(s);
+  build(s);
+};
+document.getElementById('settingsBtn').onclick = () => {
+  document.getElementById('panel').classList.toggle('open');
+};
+document.querySelectorAll('#bar button[data-speed]').forEach((b) => {
+  b.onclick = () => {
+    simSpeed = Number(b.dataset.speed);
+    highlight('data-speed', simSpeed);
+  };
+});
+document.querySelectorAll('#bar button[data-view]').forEach((b) => {
+  b.onclick = () => {
+    viewMode = b.dataset.view;
+    highlight('data-view', viewMode);
+    controls.enabled = viewMode === 'orbit';
+    if (viewMode === 'orbit' && sim) snapOrbit();
+    if (viewMode !== 'top') camera.up.set(0, 1, 0);
+  };
+});
+window.addEventListener('keydown', (e) => {
+  if (e.code !== 'Space') return;
+  const el = document.activeElement;
+  if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA')) return;
+  e.preventDefault();
+  setPaused(!paused);
+});
+window.addEventListener('resize', () => {
+  camera.aspect = window.innerWidth / window.innerHeight;
+  camera.updateProjectionMatrix();
+  renderer.setSize(window.innerWidth, window.innerHeight);
+});
+
+let last = performance.now();
+function frame(now) {
+  requestAnimationFrame(frame);
+  const realDt = Math.min(0.05, (now - last) / 1000);
+  last = now;
+  if (sim && !paused) {
+    sim.acc += realDt * simSpeed;
+    let steps = 0;
+    while (sim.acc >= FIXED && steps < MAX_STEPS) {
+      physicsStep();
+      sim.acc -= FIXED;
+      steps++;
+    }
+    if (steps === MAX_STEPS) sim.acc = 0;
+  }
+  if (sim) {
+    syncGraphics();
+    updateCamera();
+  }
+  renderer.render(scene, camera);
+}
+
+await RAPIER.init();
+writeSettings(DEFAULTS);
+build(DEFAULTS);
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

