function addWheel(name, axleLocal, z, shockLimit) {
  const x = startCenter + axleLocal;
  const y = wheelR;
  const desc = RAPIER.RigidBodyDesc.dynamic()
    .setTranslation(x, y, z)
    .setCanSleep(true)
    .setCcdEnabled(true)
    .setLinearDamping(0.02)
    .setAngularDamping(0.02);
  const body = world.createRigidBody(desc);
  const mass = massOf('wheel', 4);
  const col = world.createCollider(
    RAPIER.ColliderDesc.cylinder(wheelW * 0.5, wheelR)
      .setRotation({ x: Math.SQRT1_2, y: 0, z: 0, w: Math.SQRT1_2 })
      .setFriction(Math.min(1.35, s.groundFriction + 0.15))
      .setRestitution(0.03)
      .setDensity(mass / Math.max(1e-4, Math.PI * wheelR * wheelR * wheelW))
      .setCollisionGroups(groups(G_CAR, G_GROUND | G_BRICK | G_CAR))
      .setActiveEvents(RAPIER.ActiveEvents?.CONTACT_FORCE_EVENTS ?? 2)
      .setContactForceEventThreshold(250),
    body
  );
  const vis = new THREE.Group();
  const tire = new THREE.Mesh(new THREE.CylinderGeometry(wheelR, wheelR, wheelW, 18), tireMat);
  tire.geometry.rotateX(Math.PI / 2);
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(wheelR * 0.58, wheelR * 0.58, wheelW * 0.72, 14), rimMat);
  rim.geometry.rotateX(Math.PI / 2);
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(wheelR * 0.18, wheelR * 0.18, wheelW * 0.8, 10), trimMat);
  hub.geometry.rotateX(Math.PI / 2);
  vis.add(tire, rim, hub);
  vis.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  group.add(vis);
  const part = {
    name, type: 'car', body, mesh: vis, collider: col,
    pos: { x, y, z }, hx: wheelR, hy: wheelR, hz: wheelW * 0.5,
    halfH: wheelR, blobR: wheelR * 0.95,
    contactLimit: 5200, hit: 0, isWheel: true, shockLimit
  };
  meta.set(body.handle, part);
  parts.push(part);
  state.wheels.push(part);
  body.wakeUp();
  return part;
}

